#!/usr/bin/env node
// hood-stock-lp selftest: offline math/encoding vectors, plus --live for
// read-only checks against Robinhood Chain (no keys, no writes, no cost).
// Exit 0 = all pass; any failure exits 1 with the failing check named.
//
// The VECTORS below are ground truth: generated by the Midpoint engine's
// viem-based encoders (engine/v4.mjs — the code running the live house book)
// with Date.now frozen to 1756200000000 (deadline 1756201200). Our zero-dep
// builders must reproduce them BYTE FOR BYTE.

import { MARKETS, USDG, SEL, NPM_V3, MAX_UINT128, getMarket } from "./lib/markets.mjs";
import {
  addrWord,
  uintWord,
  intWord,
  toInt,
  multicall,
  ethCall,
  wordAt,
  toBigInt,
  toAddr,
  strip0x,
  encBytesArray,
} from "./lib/chain.mjs";
import {
  priceFromSqrtX96,
  tickFromPrice,
  priceFromTick,
  ticksForBand,
  buildBand,
  stockShare,
  wFromIV,
  liquidityForAmounts,
  amountsForLiquidity,
  inRange,
} from "./lib/math.mjs";
import {
  poolKeyFor,
  buyStockZeroForOne,
  swapData,
  mintData,
  burnData,
  quoterData,
  permit2ApproveData,
  quoteSwap,
  v4PoolState,
  unpackTicks,
} from "./lib/v4.mjs";

const results = [];
function check(name, cond, detail = "") {
  results.push({ name, pass: !!cond, detail });
}
function approx(a, b, tolPct = 0.01) {
  return Math.abs(a / b - 1) < tolPct;
}

const DEADLINE = 1756201200; // frozen in the vector generator
const OWNER = "0x1111111111111111111111111111111111111111";

// --- word encoding ---
check("int24 -60000 two's complement", intWord(-60000).endsWith("ff15a0") && /^f+/.test(intWord(-60000)));
check("int24 +60 plain", intWord(60) === uintWord(60));
check("sign-extend decode", toInt("f".repeat(58) + "f15a0".padStart(6, "f")) === -60000n);
check("addr padding", addrWord(USDG).length === 64);
check("max128 word", uintWord(MAX_UINT128) === "00000000000000000000000000000000" + "f".repeat(32));

// --- orientation math: BOTH cases ---
// stock-first (usdgIs0=false, e.g. TSLA): price = raw*1e12, tick up = price up
// vector: $300 -> raw = 3e-10 -> sqrtP = 2^96*sqrt(3e-10)
const sqrtTsla = BigInt(Math.round(2 ** 96 * Math.sqrt(300e-12)));
check("price from sqrtX96 (stock-first $300)", approx(priceFromSqrtX96(sqrtTsla, false), 300, 0.001));
// USDG-first (usdgIs0=true, e.g. AAPL): price = 1e12/raw, tick up = price DOWN
const sqrtAapl = BigInt(Math.round(2 ** 96 * Math.sqrt(1e12 / 230)));
check("price from sqrtX96 (USDG-first $230)", approx(priceFromSqrtX96(sqrtAapl, true), 230, 0.001));

for (const [p, inv] of [[300, false], [22.4, false], [230, true], [83.5, true]]) {
  const t = Math.round(tickFromPrice(p, inv));
  check(`tick/price roundtrip $${p} (usdgIs0=${inv})`, approx(priceFromTick(t, inv), p, 0.001));
}

// band inversion: USDG-first flips which edge maps to which tick
const bInv = ticksForBand(300, 322, true, 60);
check("USDG-first: low price -> UPPER tick", approx(priceFromTick(bInv.tickUpper, true), bInv.bandLow, 0.001));
check("USDG-first band contains request", bInv.bandLow <= 300 && bInv.bandHigh >= 322);
const bStd = ticksForBand(300, 322, false, 60);
check("stock-first: low price -> LOWER tick", approx(priceFromTick(bStd.tickLower, false), bStd.bandLow, 0.001));
check("stock-first band contains request", bStd.bandLow <= 300 && bStd.bandHigh >= 322);
check("ticks snapped", bInv.tickLower % 60 === 0 && bInv.tickUpper % 60 === 0 && bStd.tickLower % 60 === 0);
const tiny = ticksForBand(310.0, 310.01, false, 60);
check("1-spacing floor", tiny.tickUpper - tiny.tickLower === 60);

// band construction
const b2 = buildBand(310, 312, 0.035, "standard", false, 60);
check("buildBand centers between pool and quote", b2.bandLow < 311 && b2.bandHigh > 311);
const b3 = buildBand(310, 312, 5.0, "wide", false, 60);
check("buildBand caps at ±35%", b3.bandHigh / 311 < 1.4);
let threw = false;
try {
  buildBand(310, 312, 0, "standard", false, 60);
} catch {
  threw = true;
}
check("no vol input -> throws (fail closed)", threw);

// stock share + liquidity round trip
check("share at center ~0.4-0.6", stockShare(311, 300, 322) > 0.4 && stockShare(311, 300, 322) < 0.6);
check("share below band = 1", stockShare(290, 300, 322) === 1);
check("share above band = 0", stockShare(330, 300, 322) === 0);
check("wFromIV(0.28) ~ 3.9%", approx(wFromIV(0.28), 0.0394, 0.02));
{
  // L sized from amounts must reproduce ~those amounts (minus haircut)
  const tl = -60000, tu = -54000;
  const sqrtP = 1.0001 ** (-57000 / 2);
  const a0 = 3e17, a1 = 5e7; // raw currency0 (stock 18dp), currency1 (USDG 6dp)
  const L = liquidityForAmounts(sqrtP, tl, tu, BigInt(a0), BigInt(a1), 0);
  const { amt0, amt1 } = amountsForLiquidity(L, -57000, sqrtP, tl, tu);
  check("liquidity round trip stays under caps", amt0 <= a0 && amt1 <= a1);
  check("liquidity round trip uses >90% of one side", amt0 / a0 > 0.9 || amt1 / a1 > 0.9);
  check("in-range check", inRange(-57000, tl, tu) && !inRange(-54000, tl, tu));
}

// unpackTicks (v4 PositionInfo packing)
{
  const info = (BigInt(0xffff2d10 & 0xffffff) << 32n) | (BigInt(0xff15a0 & 0xffffff) << 8n);
  const { tickLower, tickUpper } = unpackTicks(info);
  check("unpackTicks sign-extends", tickLower === -60000 && tickUpper === -54000);
}

// --- BYTE-FOR-BYTE calldata vs the engine's viem encoders ---
const V = {
  v4SwapBuyTSLA: "",
  v4MintTSLA: "",
  v4BurnTSLA: "",
  quoterTSLA: "",
  permit2Approve: "0x87517c45000000000000000000000000322f0929c4625ed5bad873c95208d54e1c003b2d0000000000000000000000008876789976decbfcbbbe364623c63652db8c0904000000000000000000000000ffffffffffffffffffffffffffffffffffffffff0000000000000000000000000000000000000000000000000000000068d50940",
  v3MintMSFT: "",
  v3SwapBuyGME: "",
  v3Decrease: "",
  v3Collect: "0xfc6f78650000000000000000000000000000000000000000000000000000000000095cf9000000000000000000000000111111111111111111111111111111111111111100000000000000000000000000000000ffffffffffffffffffffffffffffffff00000000000000000000000000000000ffffffffffffffffffffffffffffffff",
};

const keyTSLA = poolKeyFor(getMarket("TSLA"));
const keyAAPL = poolKeyFor(getMarket("AAPL"));
check("poolKey sort (stock-first TSLA)", keyTSLA.currency0.toLowerCase() === MARKETS.TSLA.token.toLowerCase());
check("poolKey sort (USDG-first AAPL)", keyAAPL.currency0.toLowerCase() === USDG.toLowerCase());
check("zeroForOne: buy on USDG-first = true", buyStockZeroForOne(getMarket("AAPL")) === true);
check("zeroForOne: buy on stock-first = false", buyStockZeroForOne(getMarket("TSLA")) === false);

check(
  "v4 UR swap bytes == engine viem output",
  swapData(keyTSLA, false, 50_000_000n, 138000000000000000n, DEADLINE).toLowerCase() === V.v4SwapBuyTSLA
);
check(
  "v4 POSM mint bytes == engine viem output",
  mintData(keyTSLA, -60000, -54000, 123456789012n, 300000000000000000n, 50_000_000n, OWNER, DEADLINE).toLowerCase() === V.v4MintTSLA
);
check(
  "v4 POSM burn bytes == engine viem output",
  burnData(keyTSLA, 4242n, OWNER, DEADLINE).toLowerCase() === V.v4BurnTSLA
);
check(
  "v4 quoter bytes == viem output",
  ("0x" + strip0x(quoterData(keyTSLA, false, 50_000_000n))).toLowerCase() === V.quoterTSLA
);
check(
  "permit2 approve bytes == viem output",
  ("0x" + strip0x(permit2ApproveData(MARKETS.TSLA.token, "0x8876789976decbfcbbbe364623c63652db8c0904", 1758792000))).toLowerCase() === V.permit2Approve
);

// v3 calldata is selector + flat words — rebuild exactly as entry/exit do
const v3Mint =
  SEL.mintV3 +
  addrWord(USDG) +
  addrWord(MARKETS.MSFT.token) +
  uintWord(3000) +
  intWord(-276600) +
  intWord(-270000) +
  uintWord(50_000_000n) +
  uintWord(90000000000000000n) +
  uintWord(0) +
  uintWord(0) +
  addrWord(OWNER) +
  uintWord(DEADLINE);
check("v3 NPM mint bytes == viem output", v3Mint.toLowerCase() === V.v3MintMSFT);
const v3Swap =
  SEL.exactInputSingle +
  addrWord(USDG) +
  addrWord(MARKETS.GME.token) +
  uintWord(10000) +
  addrWord(OWNER) +
  uintWord(50_000_000n) +
  uintWord(2700000000000000000n) +
  uintWord(0);
check("v3 SwapRouter02 bytes == viem output", v3Swap.toLowerCase() === V.v3SwapBuyGME);
const v3Dec =
  SEL.decreaseLiquidity + uintWord(613625n) + uintWord(987654321n) + uintWord(0) + uintWord(0) + uintWord(DEADLINE);
check("v3 decreaseLiquidity bytes == viem output", v3Dec.toLowerCase() === V.v3Decrease);
const v3Col =
  SEL.collect + uintWord(613625n) + addrWord(OWNER) + uintWord(MAX_UINT128) + uintWord(MAX_UINT128);
check("v3 collect bytes == viem output", v3Col.toLowerCase() === V.v3Collect);

// NPM multicall(bytes[]) wrapper shape: selector + head offset + array
{
  const inner = [strip0x(v3Dec), strip0x(v3Col)];
  const mc = SEL.npmMulticall + uintWord(0x20) + encBytesArray(inner);
  const no0x = strip0x(mc);
  check(
    "v3 multicall wrapper shape",
    no0x.slice(0, 8) === "ac9650d8" &&
      toBigInt(wordAt(no0x.slice(8), 1)) === 2n && // array length
      no0x.includes(strip0x(V.v3Decrease).slice(8)) // payload embedded intact
  );
}

// --- live (read-only) ---
if (process.argv.includes("--live")) {
  const names = Object.keys(MARKETS);
  const v3Names = names.filter((m) => MARKETS[m].venue === "v3");
  const v4Names = names.filter((m) => MARKETS[m].venue === "v4");

  // token decimals: every stock 18, USDG 6 (half the price bugs in the wild
  // come from assuming the wrong side's decimals)
  const decRes = await multicall([
    { to: USDG, data: SEL.decimals },
    ...names.map((m) => ({ to: MARKETS[m].token, data: SEL.decimals })),
  ]);
  check("live USDG decimals = 6", decRes[0].ok && toBigInt(wordAt(decRes[0].data, 0)) === 6n);
  names.forEach((m, i) => {
    check(`live ${m} token decimals = 18`, decRes[i + 1].ok && toBigInt(wordAt(decRes[i + 1].data, 0)) === 18n);
  });

  // v3 pools: token0/token1/fee prove the table's usdgIs0 and fee; slot0
  // price must be sane and consistent with the tick
  const v3Res = await multicall(
    v3Names.flatMap((m) => [
      { to: MARKETS[m].pool, data: SEL.slot0 },
      { to: MARKETS[m].pool, data: SEL.token0 },
      { to: MARKETS[m].pool, data: SEL.token1 },
      { to: MARKETS[m].pool, data: SEL.feeCall },
    ])
  );
  v3Names.forEach((m, i) => {
    const M = MARKETS[m];
    const [slot0, t0, t1, fee] = v3Res.slice(i * 4, i * 4 + 4);
    const expected0 = (M.usdgIs0 ? USDG : M.token).toLowerCase();
    const expected1 = (M.usdgIs0 ? M.token : USDG).toLowerCase();
    check(`live ${m} v3 token0 matches usdgIs0`, t0.ok && toAddr(wordAt(t0.data, 0)).toLowerCase() === expected0);
    check(`live ${m} v3 token1 matches usdgIs0`, t1.ok && toAddr(wordAt(t1.data, 0)).toLowerCase() === expected1);
    check(`live ${m} v3 fee matches table`, fee.ok && Number(toBigInt(wordAt(fee.data, 0))) === M.fee);
    const price = slot0.ok ? priceFromSqrtX96(toBigInt(wordAt(slot0.data, 0)), M.usdgIs0) : 0;
    const tick = slot0.ok ? Number(toInt(wordAt(slot0.data, 1))) : null;
    check(`live ${m} v3 price sane`, price > 0.5 && price < 50000, `$${price.toFixed(2)}`);
    check(`live ${m} v3 tick matches price`, tick !== null && approx(priceFromTick(tick, M.usdgIs0), price, 0.001));
  });

  // v4 pools: StateView slot0 sane, and a $1 quoter round-trip proves the
  // poolKey->poolId mapping (a wrong key reverts or prices garbage)
  for (const m of v4Names) {
    const M = MARKETS[m];
    let price = 0;
    try {
      const ps = await v4PoolState(M.pool, M.usdgIs0);
      price = ps.price;
      check(`live ${m} v4 price sane`, price > 0.5 && price < 50000, `$${price.toFixed(2)}`);
      check(`live ${m} v4 tick matches price`, approx(priceFromTick(ps.tick, M.usdgIs0), price, 0.001));
    } catch (e) {
      check(`live ${m} v4 StateView read`, false, String(e.message).slice(0, 80));
      continue;
    }
    try {
      const key = poolKeyFor(M);
      const { amountOut } = await quoteSwap(key, buyStockZeroForOne(M), 1_000_000n); // $1 in
      const implied = 1 / (Number(amountOut) / 1e18);
      check(
        `live ${m} v4 quoter agrees with pool (poolKey<->poolId proof)`,
        amountOut > 0n && approx(implied, price, 0.15),
        `quoter implies $${implied.toFixed(2)} vs pool $${price.toFixed(2)}`
      );
    } catch (e) {
      check(`live ${m} v4 quoter`, false, String(e.message).slice(0, 80));
    }
  }

  // shared infra sanity
  const [npmCode] = await Promise.all([ethCall(NPM_V3, SEL.balanceOf + addrWord(OWNER)).catch(() => null)]);
  check("live v3 NPM answers balanceOf", npmCode !== null);
}

// --- report ---
const failed = results.filter((r) => !r.pass);
for (const r of results) {
  console.error(`${r.pass ? "PASS" : "FAIL"}  ${r.name}${r.detail ? `  (${r.detail})` : ""}`);
}
console.log(JSON.stringify({ ok: failed.length === 0, checks: results.length, failed: failed.map((f) => f.name) }));
process.exit(failed.length === 0 ? 0 : 1);
